/**
 * The real-world outcome of the last gated correction (Task 9's training
 * signal), marshalled across the FFI. Mirrors [`AutocorrectOutcome`] 1:1.
 */

enum class FfiAutocorrectOutcome {
    
    /**
     * The user reverted/undid it: push the gate toward "withhold".
     */
    REVERTED,
    /**
     * The user kept it, with no strong signal either way.
     */
    KEPT,
    /**
     * The user typed on past it cleanly: a confirming signal.
     */
    REACHED;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeFfiAutocorrectOutcome: FfiConverterRustBuffer<FfiAutocorrectOutcome> {
    override fun read(buf: ByteBuffer) = try {
        FfiAutocorrectOutcome.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: FfiAutocorrectOutcome) = 4UL

    override fun write(value: FfiAutocorrectOutcome, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







/**
 * The single flat error the whole surface returns. Mirrors [`FeatherKeyError`]
 * plus the two FFI-only failures (bad key length, store-open failure).
 */
sealed class FfiException: kotlin.Exception() {
    
    class NoLanguages(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class Lexicon(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class Locale(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class EmptyLayout(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class TouchModel(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class Store(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class BadKeyLength(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    class StoreOpen(
        ) : FfiException() {
        override val message
            get() = ""
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        

        return when(buf.getInt()) {
            1 -> FfiException.NoLanguages()
            2 -> FfiException.Lexicon()
            3 -> FfiException.Locale()
            4 -> FfiException.EmptyLayout()
            5 -> FfiException.TouchModel()
            6 -> FfiException.Store()
            7 -> FfiException.BadKeyLength()
            8 -> FfiException.StoreOpen()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.NoLanguages -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Lexicon -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Locale -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.EmptyLayout -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.TouchModel -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Store -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.BadKeyLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.StoreOpen -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.NoLanguages -> {
                buf.putInt(1)
                Unit
            }
            is FfiException.Lexicon -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.Locale -> {
                buf.putInt(3)
                Unit
            }
            is FfiException.EmptyLayout -> {
                buf.putInt(4)
                Unit
            }
            is FfiException.TouchModel -> {
                buf.putInt(5)
                Unit
            }
            is FfiException.Store -> {
                buf.putInt(6)
                Unit
            }
            is FfiException.BadKeyLength -> {
                buf.putInt(7)
                Unit
            }
            is FfiException.StoreOpen -> {
                buf.putInt(8)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



